111		} else {
112			orderBy = append(orderBy, "created_ts "+order)
113		}
114		// Add id as final tie-breaker
115		orderBy = append(orderBy, "id DESC")
116		fields := []string{
117			`memo.id AS id`,
118			`memo.uid AS uid`,
119			`memo.creator_id AS creator_id`,
120			`memo.created_ts AS created_ts`,
121			`memo.updated_ts AS updated_ts`,
122			`memo.row_status AS row_status`,
123			`memo.visibility AS visibility`,
124			`memo.pinned AS pinned`,
125			`memo.payload AS payload`,
126			`CASE WHEN parent_memo.uid IS NOT NULL THEN parent_memo.uid ELSE NULL END AS parent_uid`,
127		}
128		if !find.ExcludeContent {
129			fields = append(fields, `memo.content AS content`)
130		}
131	
132		query := `SELECT ` + strings.Join(fields, ", ") + `
133			FROM memo
134			LEFT JOIN "user" AS memo_creator ON memo.creator_id = memo_creator.id
135			LEFT JOIN memo_relation ON memo.id = memo_relation.memo_id AND memo_relation.type = 'COMMENT'
136			LEFT JOIN memo AS parent_memo ON memo_relation.related_memo_id = parent_memo.id
137			WHERE ` + strings.Join(where, " AND ") + `
138			ORDER BY ` + strings.Join(orderBy, ", ")
