143			}
144		}
145	
146		rows, err := d.db.QueryContext(ctx, query, args...)
147		if err != nil {
148			return nil, err
149		}
150		defer rows.Close()
151	
152		list := make([]*store.Memo, 0)
153		for rows.Next() {
154			var memo store.Memo
155			var payloadBytes []byte
156			dests := []any{
157				&memo.ID,
158				&memo.UID,
159				&memo.CreatorID,
160				&memo.CreatedTs,
161				&memo.UpdatedTs,
162				&memo.RowStatus,
163				&memo.Visibility,
164				&memo.Pinned,
