214			set, args = append(set, "row_status = "+placeholder(len(args)+1)), append(args, *v)
215		}
216		if v := update.Content; v != nil {
217			set, args = append(set, "content = "+placeholder(len(args)+1)), append(args, *v)
218		}
219		if v := update.Visibility; v != nil {
220			set, args = append(set, "visibility = "+placeholder(len(args)+1)), append(args, *v)
